framework/briefing/commitments.py:
"""Ticket 10: typed commitment registry loading (fail closed).

The real file lives outside the repo; only synthetic fixtures and
``tmp_path`` files are read in tests.
"""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any, cast

from pydantic import ValidationError

from framework.briefing.gate import action_targets_repo, text_check_codes
from framework.briefing.schemas import Commitment

_UNSET = "unset"
_UNREADABLE = "unreadable"
_NOT_UTF8 = "not_utf8"
_INVALID_JSON = "invalid_json"
_NOT_A_LIST = "not_a_list"
_EMPTY = "empty"
_INVALID_ITEM = "invalid_item"
_DUPLICATE_ID = "duplicate_id"
_TITLE_FAILED = "title_failed"


@dataclass(frozen=True)
class LoadedCommitments:
    """Loaded commitments plus their availability (fail closed)."""

    commitments: tuple[Commitment, ...]
    available: bool
    reason: str | None


def _failed(reason: str) -> LoadedCommitments:
    return LoadedCommitments((), False, reason)


def load_commitments(
    environ: Mapping[str, str] | None = None,
    *,
    private_terms: tuple[str, ...] = (),
    forbidden_raw_literals: tuple[str, ...] = (),
) -> LoadedCommitments:
    """Load the JSON commitment list named by ``IKIGAI_COMMITMENTS_FILE``.

    Reads the variable at call time only. Any failure returns no
    commitments with ``available`` False and one closed reason value, with
    no exception and no path or file content in any message, output or
    log. The whole file is rejected when any title fails the title
    checks.
    """
    env: Mapping[str, str] = os.environ if environ is None else environ
    raw_path = env.get("IKIGAI_COMMITMENTS_FILE", "")
    if not raw_path:
        return _failed(_UNSET)
    try:
        data = Path(raw_path).read_bytes()
    except (OSError, ValueError):
        return _failed(_UNREADABLE)
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return _failed(_NOT_UTF8)
    try:
        parsed: Any = json.loads(text)
    except (ValueError, RecursionError):
        return _failed(_INVALID_JSON)
    if not isinstance(parsed, list):
        return _failed(_NOT_A_LIST)
    items = cast("list[Any]", parsed)
    if not items:
        return _failed(_EMPTY)
    commitments: list[Commitment] = []
    try:
        for item in items:
            commitments.append(Commitment.model_validate(item))
    except (ValidationError, TypeError):
        return _failed(_INVALID_ITEM)
    seen: set[str] = set()
    for commitment in commitments:
        if commitment.id in seen:
            return _failed(_DUPLICATE_ID)
        seen.add(commitment.id)
    for commitment in commitments:
        if text_check_codes(
            commitment.title,
            private_terms=private_terms,
            forbidden_raw_literals=forbidden_raw_literals,
        ):
            return _failed(_TITLE_FAILED)
        if action_targets_repo(commitment.title):
            return _failed(_TITLE_FAILED)
    return LoadedCommitments(tuple(commitments), True, None)

framework/briefing/context.py:
"""Ticket 8: gate reference data (``GateContext``) and private-terms loading.

Building a context is the only place env/files are read;
``evaluate_briefing`` itself is pure.
"""

from __future__ import annotations

import os
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import time
from pathlib import Path
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from pydantic import AwareDatetime, Field, field_validator, model_validator

from framework.briefing.schemas import Briefing, Commitment
from framework.schemas.base import SchemaModel
from framework.schemas.core import Fact
from framework.schemas.events import NonEmptyStr


class TimeInterval(SchemaModel):
    """Half-open ``[start, end)`` interval."""

    start: AwareDatetime
    end: AwareDatetime

    @model_validator(mode="after")
    def _end_after_start(self) -> TimeInterval:
        if self.end <= self.start:
            raise ValueError("interval end must be after start")
        return self


class MetricSnapshot(SchemaModel):
    """Point-in-time metric values; empty is valid (claims-free briefings)."""

    values: dict[NonEmptyStr, float] = Field(default_factory=dict)

    @field_validator("values")
    @classmethod
    def _finite_values(cls, values: dict[str, float]) -> dict[str, float]:
        import math

        for metric_id, value in values.items():
            if not math.isfinite(value):
                raise ValueError(f"metric value must be finite: {metric_id}")
        return values


class ProfileLimits(SchemaModel):
    """Typed limits a caller encodes; the gate never parses markdown."""

    timezone: NonEmptyStr
    allowed_start: time
    allowed_end: time
    max_actions: int = Field(default=3, ge=1, le=3)

    @field_validator("timezone")
    @classmethod
    def _known_timezone(cls, timezone: str) -> str:
        try:
            ZoneInfo(timezone)
        except ZoneInfoNotFoundError as exc:
            raise ValueError(f"unknown timezone: {timezone}") from exc
        return timezone

    @model_validator(mode="after")
    def _same_day_window(self) -> ProfileLimits:
        if self.allowed_start >= self.allowed_end:
            raise ValueError("allowed_start must be before allowed_end")
        return self


class GateContext(SchemaModel):
    """Reference data the gate reconciles one briefing against."""

    facts: dict[NonEmptyStr, Fact] = Field(default_factory=dict)
    metrics: MetricSnapshot = Field(default_factory=MetricSnapshot)
    parent_briefing: Briefing | None = None
    parent_metrics: MetricSnapshot | None = None
    free_intervals: tuple[TimeInterval, ...] = ()
    busy_intervals: tuple[TimeInterval, ...] = ()
    limits: ProfileLimits
    check_slot: bool = True
    private_terms: tuple[str, ...] = ()
    private_terms_available: bool = False
    raw_metric_ids: frozenset[NonEmptyStr] = frozenset()
    forbidden_raw_literals: tuple[NonEmptyStr, ...] = ()
    commitments: tuple[Commitment, ...] = ()
    commitments_available: bool = False

    @field_validator("facts")
    @classmethod
    def _keys_match_ids(cls, facts: dict[str, Fact]) -> dict[str, Fact]:
        for key, fact in facts.items():
            if key != fact.id:
                raise ValueError("facts key must equal its Fact.id")
        return facts

    @model_validator(mode="after")
    def _parent_pair(self) -> GateContext:
        if (self.parent_briefing is None) != (self.parent_metrics is None):
            raise ValueError(
                "parent_briefing and parent_metrics must both be present or both absent"
            )
        return self

    @model_validator(mode="after")
    def _unique_commitment_ids(self) -> GateContext:
        seen: set[str] = set()
        for commitment in self.commitments:
            if commitment.id in seen:
                raise ValueError("commitment ids must be unique")
            seen.add(commitment.id)
        return self


@dataclass(frozen=True)
class PrivateTerms:
    """Loaded private terms plus their availability (fail closed)."""

    terms: tuple[str, ...]
    available: bool


def load_private_terms(
    environ: Mapping[str, str] | None = None,
    *,
    allow_missing_for_tests: bool = False,
) -> PrivateTerms:
    """Load private terms from ``deny-terms.txt`` in ``HIDDEN_CRITERIA_DIR``.

    The directory may hold other criteria files, so only ``deny-terms.txt``
    is read. The file holds one term per line; blank lines and lines
    starting with ``#`` are ignored. Matching is case-insensitive; terms of
    3 characters or fewer match whole words only, longer terms match as
    substrings (see the gate). Reads the variable at call time only.
    Unset/empty passes terms only when the caller passes
    ``allow_missing_for_tests=True``; every production caller uses the
    default. A missing file, a file with no terms, a non-UTF-8 file, or any
    line starting with ``- `` or ``* `` fails closed with no exception and
    no path in any message. Terms are never logged. The one-term-per-line
    ``deny-terms.txt`` layout is an assumption (see the session note).
    """
    env: Mapping[str, str] = os.environ if environ is None else environ
    raw_dir = env.get("HIDDEN_CRITERIA_DIR", "")
    if not raw_dir:
        return PrivateTerms((), available=allow_missing_for_tests)
    try:
        data = (Path(raw_dir) / "deny-terms.txt").read_bytes()
    except OSError:
        return PrivateTerms((), available=False)
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return PrivateTerms((), available=False)
    terms: list[str] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith(("- ", "* ")):
            return PrivateTerms((), available=False)
        if stripped not in terms:
            terms.append(stripped)
    if not terms:
        return PrivateTerms((), available=False)
    return PrivateTerms(tuple(terms), available=True)

framework/briefing/gate.py:
"""Ticket 8: deterministic briefing gate (L0 structure, L1 rules, L1b).

No network, no model call, no env read, no clock read: all times come from
the briefing/context. Messages never interpolate a matched secret, email,
private term, or raw value. Identical ``(code, location)`` pairs are
de-duplicated once at the end; the result is sorted by
``(layer, code, location)`` so section input order cannot change it.
"""

from __future__ import annotations

import itertools
import re
from collections import Counter
from collections.abc import Collection, Mapping
from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Any, Literal, cast
from zoneinfo import ZoneInfo

from pydantic import ValidationError

import framework.briefing.claim_text as claim_text_lists
from framework.briefing.claim_text import (
    STEADY_WORDS,
    claim_text_codes,
    counted_periods,
    direction_side,
    drop_tied_to,
    fact_claim_codes,
    has_negator,
    hyphen_directions,
    stated_zero_code,
    steady_same_counts,
    without_count_held,
)

UP_WORDS = claim_text_lists.UP_WORDS
DOWN_WORDS = claim_text_lists.DOWN_WORDS
PERIOD_WORDS = claim_text_lists.PERIOD_WORDS
ADVICE_PHRASES = claim_text_lists.ADVICE_PHRASES
from framework.briefing.context import GateContext, ProfileLimits, TimeInterval
from framework.briefing.labels import MetricBinding, metric_label_binding
from framework.briefing.normalize import normalize_text
from framework.briefing.numbers import (
    blank_known_names,
    extract_number_tokens,
    find_known_names,
    token_backed_by,
)
from framework.briefing.schemas import Action, Briefing, Claim

Layer = Literal["L0", "L1", "L1b"]

REQUIRED_SECTIONS = ("overall_state", "working", "not_working", "actions")
KNOWN_SECTION_TYPES = frozenset(
    ["overall_state", "since_last", "working", "not_working", "actions"]
)

_SECRET_PATTERNS = tuple(
    re.compile(pattern, re.IGNORECASE)
    for pattern in (
        r"\bghp_[A-Za-z0-9_-]{16,}",
        r"\bgho_[A-Za-z0-9_-]{16,}",
        r"\bgithub_pat_[A-Za-z0-9_-]{16,}",
        r"\bglpat-[A-Za-z0-9_-]{16,}",
        r"\bsk-[A-Za-z0-9_-]{16,}",
        r"\bAKIA[A-Za-z0-9_-]{16,}",
        r"\bxox[baprs]-[A-Za-z0-9_-]{16,}",
        r"\bBearer\s+\S{16,}",
        r"-----BEGIN [A-Za-z0-9 ]*PRIVATE KEY-----",
        r"(?:api[_-]?key|secret|token|password)\s*[:=]\s*\S+",
        r"\b[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.ts\.net\b",
    )
)
_EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
_PHONE_RE = re.compile(r"\+\d[\d ()-]{7,}\d")
_REPO_TERMS = ("ikigai-loop", "ikigai_loop", "ikigai loop")
_ADVICE_SINGLES = frozenset(
    [
        "should",
        "must",
        "diet",
        "diets",
        "calorie",
        "calories",
        "medication",
        "medications",
        "medicine",
        "medicines",
        "dose",
        "doses",
        "dosage",
        "dosages",
        "symptom",
        "symptoms",
        "diagnosis",
        "diagnoses",
        "treatment",
        "treatments",
        "therapy",
        "therapies",
        "intensity",
        "shouldn't",
        "mustn't",
    ]
)
_PERIOD_ORDER = {"earlier": 0, "prior": 1, "last": 2}
_DIRECTION_TOKEN_RE = re.compile(r"\w+(?:-\w+)*")
_PERIOD_MESSAGE = "period words do not match the cited metrics"


def _squashed_hit(normalized: str, term: str) -> bool:
    """Token-aligned squashed match for terms of 5 or more characters."""
    squashed: list[str] = []
    index_map: list[int] = []
    for pos, char in enumerate(normalized):
        if not char.isalnum():
            continue
        squashed.append(char)
        index_map.append(pos)
    if not squashed:
        return False
    squashed_term = "".join(c for c in term if c.isalnum())
    if len(squashed_term) < 5:
        return False
    joined = "".join(squashed)
    start = 0
    while True:
        index = joined.find(squashed_term, start)
        if index < 0:
            return False
        first = index_map[index]
        last = index_map[index + len(squashed_term) - 1]
        before = normalized[first - 1] if first > 0 else ""
        after = normalized[last + 1] if last + 1 < len(normalized) else ""
        if not (before.isalnum() or before == "_") and not (
            after.isalnum() or after == "_"
        ):
            return True
        start = index + 1


def _sequence_hit(normalized: str, literal: str) -> bool:
    """Token-sequence match of ``literal`` ignoring punctuation between."""
    want = _DIRECTION_TOKEN_RE.findall(literal)
    if not want:
        return False
    got = _DIRECTION_TOKEN_RE.findall(normalized)
    return any(got[i : i + len(want)] == want for i in range(len(got) - len(want) + 1))


def text_check_codes(
    text: str,
    *,
    private_terms: tuple[str, ...] = (),
    forbidden_raw_literals: tuple[str, ...] = (),
) -> tuple[str, ...]:
    """L1 text verdicts for one text; never ``L1_ACTION_TARGETS_REPO``.

    Matching runs on the ``normalize_text`` copy (casefolded locally), so
    full-width, accented and confusable spellings read as their base
    letters. Unsafe characters are stripped for matching here and never
    reported; the claim path rejects them outright instead.
    """
    codes: list[str] = []
    if any(pattern.search(text) for pattern in _SECRET_PATTERNS):
        codes.append("L1_SECRET")
    if _EMAIL_RE.search(text) or _PHONE_RE.search(text):
        codes.append("L1_PII")
    normalized = normalize_text(text).casefold()
    if any(_contains_token(normalized, word) for word in _ADVICE_SINGLES) or any(
        _contains_token(normalized, phrase) for phrase in ADVICE_PHRASES
    ):
        codes.append("L1_ADVICE")
    for raw_term in private_terms:
        term = normalize_text(raw_term).casefold()
        if not term:
            continue
        if len(term) <= 3:
            hit = _contains_token(normalized, term)
        elif term in normalized:
            hit = True
        else:
            hit = _squashed_hit(normalized, term)
        if hit:
            codes.append("L1_PRIVATE_TERM")
            break
    for raw_literal in forbidden_raw_literals:
        literal = normalize_text(raw_literal).casefold()
        if literal and _sequence_hit(normalized, literal):
            codes.append("L1_RAW_VALUE")
            break
    return tuple(codes)


def action_targets_repo(text: str) -> bool:
    """Whether action text names this repo."""
    lowered = text.casefold()
    return any(term in lowered for term in _REPO_TERMS)


_ACTION_WINDOW_MESSAGES = {
    "L1_ACTION_BEFORE_SLOT": "action starts before the briefing slot",
    "L1_ACTION_IN_BUSY_INTERVAL": "action overlaps a busy interval",
    "L1_ACTION_NOT_FREE": "action is not fully inside free time",
}


def action_window_codes(
    start: datetime,
    end: datetime,
    *,
    slot: datetime,
    busy_intervals: tuple[TimeInterval, ...],
    free_intervals: tuple[TimeInterval, ...],
) -> tuple[str, ...]:
    """Window verdicts for one proposed range; no env, clock or network."""
    codes: list[str] = []
    if start < slot:
        codes.append("L1_ACTION_BEFORE_SLOT")
    if any(start < busy.end and busy.start < end for busy in busy_intervals):
        codes.append("L1_ACTION_IN_BUSY_INTERVAL")
    elif not any(
        free_start <= start and end <= free_end
        for free_start, free_end in _merge_intervals(free_intervals)
    ):
        codes.append("L1_ACTION_NOT_FREE")
    return tuple(codes)


@dataclass(frozen=True)
class Violation:
    """One stable gate finding; ``message`` never echoes matched content."""

    code: str
    layer: Layer
    location: str
    message: str


@dataclass(frozen=True)
class GateResult:
    """Sorted, de-duplicated violations for one briefing."""

    violations: tuple[Violation, ...]

    @property
    def passed(self) -> bool:
        """A briefing passes iff it has no violations."""
        return self.violations == ()


def _section_location(section_type: str) -> str:
    return f"sections[{section_type}]"


def _claim_location(section_type: str, claim_id: str) -> str:
    return f"sections[{section_type}].claims[{claim_id}]"


def _action_location(action_id: str) -> str:
    return f"sections[actions].actions[{action_id}]"


def _iter_texts(
    briefing: Briefing,
) -> tuple[tuple[str, str, str, str], ...]:
    """(kind, owner_id, text, location) for every scanned claim/action text."""
    rows: list[tuple[str, str, str, str]] = []
    for section in briefing.sections:
        for claim in section.claims:
            rows.append(
                (
                    "claim",
                    claim.id,
                    claim.text,
                    _claim_location(section.type, claim.id),
                )
            )
        for action in section.actions:
            rows.append(("action", action.id, action.text, _action_location(action.id)))
    return tuple(rows)


def _iter_claims(
    briefing: Briefing,
) -> tuple[tuple[str, Claim], ...]:
    return tuple(
        (section.type, claim)
        for section in briefing.sections
        for claim in section.claims
    )


def _iter_actions(briefing: Briefing) -> tuple[Action, ...]:
    return tuple(action for section in briefing.sections for action in section.actions)


def _collapse(text: str) -> str:
    return " ".join(text.split()).casefold()


def _contains_token(text: str, literal: str) -> bool:
    start = 0
    while True:
        index = text.find(literal, start)
        if index < 0:
            return False
        before = text[index - 1] if index > 0 else ""
        end = index + len(literal)
        after = text[end] if end < len(text) else ""
        if not (before.isalnum() or before == "_") and not (
            after.isalnum() or after == "_"
        ):
            return True
        start = index + 1


def _merge_intervals(
    intervals: tuple[TimeInterval, ...],
) -> tuple[tuple[datetime, datetime], ...]:
    spans = sorted(
        ((item.start, item.end) for item in intervals), key=lambda span: span[0]
    )
    merged: list[list[datetime]] = []
    for start, end in spans:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return tuple((start, end) for start, end in merged)


def _l0_counts(briefing: Briefing, context: GateContext) -> list[Violation]:
    violations: list[Violation] = []
    types = [section.type for section in briefing.sections]
    for section_type, count in Counter(types).items():
        if count > 1:
            violations.append(
                Violation(
                    "L0_DUPLICATE_SECTION",
                    "L0",
                    _section_location(section_type),
                    "section type appears more than once",
                )
            )
    for section_type in REQUIRED_SECTIONS:
        if section_type not in types:
            violations.append(
                Violation(
                    "L0_MISSING_SECTION",
                    "L0",
                    _section_location(section_type),
                    "required section is missing",
                )
            )
    if len(types) > 5:
        violations.append(
            Violation("L0_SECTION_COUNT", "L0", "sections", "too many sections")
        )
    for section in briefing.sections:
        if section.type == "overall_state" and not section.claims:
            violations.append(
                Violation(
                    "L0_EMPTY_SECTION",
                    "L0",
                    _section_location(section.type),
                    "section must carry at least one claim",
                )
            )
        if section.type == "since_last" and not section.claims:
            violations.append(
                Violation(
                    "L0_EMPTY_SECTION",
                    "L0",
                    _section_location(section.type),
                    "section must carry at least one claim",
                )
            )
    limit = min(3, context.limits.max_actions)
    for section in briefing.sections:
        if section.type == "actions":
            if len(section.actions) < 1 or len(section.actions) > limit:
                violations.append(
                    Violation(
                        "L0_ACTION_COUNT",
                        "L0",
                        _section_location(section.type),
                        "action count outside 1..limit",
                    )
                )
        elif section.actions:
            violations.append(
                Violation(
                    "L0_ACTION_COUNT",
                    "L0",
                    _section_location(section.type),
                    "action count outside 1..limit",
                )
            )
    seen: dict[str, str] = {}
    for section in briefing.sections:
        for claim in section.claims:
            location = _claim_location(section.type, claim.id)
            if claim.id in seen:
                violations.append(
                    Violation(
                        "L0_DUPLICATE_ID",
                        "L0",
                        location,
                        "id is used more than once",
                    )
                )
            else:
                seen[claim.id] = location
        for action in section.actions:
            location = _action_location(action.id)
            if action.id in seen:
                violations.append(
                    Violation(
                        "L0_DUPLICATE_ID",
                        "L0",
                        location,
                        "id is used more than once",
                    )
                )
            else:
                seen[action.id] = location
    return violations


_TEXT_MESSAGES = {
    "L1_SECRET": "secret-like token",
    "L1_PII": "contact detail",
    "L1_ADVICE": "advice-like wording",
    "L1_PRIVATE_TERM": "private term",
    "L1_RAW_VALUE": "raw source value",
}

_CLAIM_MESSAGES = {
    "L1_UNSAFE_TEXT": (
        "write the text plainly, with no invisible characters "
        "and no words spelled out letter by letter"
    ),
    "L1_CLAIM_LANGUAGE": "write the claim in English so it can be checked",
    "L1_ADVICE": (
        "state what the data shows, with no question, instruction or suggestion"
    ),
    "L1_PRIVATE_TERM": "private term",
    "L1_RAW_VALUE": "raw source value",
    "L1B_UNVERIFIABLE_QUANTITY": (
        "state the digits from the cited metric instead of a quantity word"
    ),
    "L1B_NEGATED_CLAIM": "state the value or direction positively",
    "L1B_COMPARISON_WORD_UNKNOWN": (
        "write the comparison with a pinned direction word, the cited "
        "label, its periods and its values only"
    ),
    "L1B_UNIT_MISMATCH": "use the unit of the cited metric",
    "L1B_METRIC_LABEL_MISMATCH": "name only the metric the claim cites",
    "L1B_VALUE_PERIOD_MISMATCH": ("write each cited value next to its own period word"),
    "L1_TEXT_TOO_LONG": "text is too long to check",
    "L1B_NUMBER_WITHOUT_METRIC_REF": "number token has no backing metric ref",
    "L1B_DIRECTION_MISMATCH": ("direction words disagree with the cited values"),
    "L1B_PERIOD_WORD_MISSING": _PERIOD_MESSAGE,
    "L1B_METRIC_LABEL_MISSING": "claim does not name the cited metric",
